-- SQL*Plus SHOW command.
-- https://docs.oracle.com/en/database/oracle/oracle-database/26/sqpug/SHOW.html
SHOW ERRORS;

SHO ERR;

SHOW ERRORS FUNCTION my_func;

SHOW ERRORS PACKAGE BODY my_schema.my_pkg;

SHOW ERRORS JAVA SOURCE my_source;

SHOW ERRORS JAVA CLASS my_class;

SHO ERRORS PROCEDURE my_proc;

SHOW ERR TRIGGER my_trigger;

SHOW ERRORS VIEW my_view;

SHOW ERRORS DIMENSION my_dimension;

SHOW ERRORS TYPE my_type;

SHOW ERRORS TYPE BODY my_type;

SHOW ERRORS PACKAGE my_pkg;

SHOW PARAMETER;

SHOW PARAMETERS sga_target;

SHOW ALL;

SHOW USER;

SHOW SGA;

SHOW LINESIZE;

SHOW CON_NAME;

show errors
